def components(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; comps=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==2 and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    r,c=st.pop(); cells.append((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<h and 0<=nc<w and g[nr][nc]==2 and not seen[nr][nc]:
                            seen[nr][nc]=True; st.append((nr,nc))
                comps.append(cells)
    return comps

def bbox(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    return min(rs),max(rs),min(cs),max(cs)

