    R, C = len(grid), len(grid[0])
    seen = set()
    comps = []
    for i in range(R):
        for j in range(C):
            if grid[i][j] == color and (i, j) not in seen:
                stack = [(i, j)]; seen.add((i, j)); comp = []
                while stack:
                    r, c = stack.pop(); comp.append((r, c))
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == color and (nr, nc) not in seen:
                                seen.add((nr, nc)); stack.append((nr, nc))
                comps.append(comp)
    return comps


def bbox(cells):
    """Bounding box (r1, r2, c1, c2) of a cell list."""
    rs = [r for r, _ in cells]; cs = [c for _, c in cells]
    return min(rs), max(rs), min(cs), max(cs)


def runs_of(seq):
    """Maximal runs of truthy values in a bool sequence as (start, end) inclusive."""
    out = []; s = None
    for i, v in enumerate(seq):
        if v and s is None: s = i
        if not v and s is not None: out.append((s, i - 1)); s = None
    if s is not None: out.append((s, len(seq) - 1))
    return out


def copy_shape(grid, color=2):
    """Relative cell offsets of a representative small copy (first 8-connected component)."""
    comp = components8(grid, color)[0]
    r1, r2, c1, c2 = bbox(comp)
    return sorted((r - r1, c - c1) for r, c in comp)


def band_ranges(grid, color=3):
    """(row_bands, col_bands) full bands occupied by `color`, as (start, end) runs."""
    rows = [any(v == color for v in row) for row in grid]
    cols = [any(row[j] == color for row in grid) for j in range(len(grid[0]))]
    return runs_of(rows), runs_of(cols)


def copy_anchors(grid, r1, r2, color=2):
    """Tile anchors (min col) of copies whose rows lie within [r1, r2]."""
    anchors = set()
    for comp in components8(grid, color):
        a, b, c, d = bbox(comp)
        if a >= r1 and b <= r2:
            anchors.add(c)
    return sorted(anchors)


def tile_of(anchor, period):
    """Nearest lattice tile index of a copy anchor under a tile period."""
    return round(anchor / period)


def restore_copies(grid, period, fill_bands, offs, color=2, bg=3):
    """Clear `bg` in the given row bands, repaint shape `offs` at missing shape-row tiles.

    fill_bands: list of (row_start, row_end, set(tile_indices)) to (re)paint.
    """
    for r1, r2, _tiles in fill_bands:
        for i in range(r1, r2 + 1):
            for j in range(len(grid[0])):
                if grid[i][j] == bg: grid[i][j] = 0
        for t in _tiles:
            a = t * period
            for dr, dc in offs:
                grid[r1 + dr][a + dc] = color
    return grid


def recolor_lattice(grid, period, old=2, new=8):
    """Recolor `old` cells on the lattice (row%period==0 and col%period==0) to `new`."""
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == old and i % period == 0 and j % period == 0:
                grid[i][j] = new
    return grid
